package org.unbiquitous.uImpala.web.impl.asset;

import org.teavm.jso.ajax.XMLHttpRequest;
import org.teavm.jso.dom.events.Event;
import org.teavm.jso.dom.events.EventListener;
import org.teavm.jso.dom.html.HTMLAudioElement;
import org.teavm.jso.dom.html.HTMLDocument;
import org.teavm.jso.dom.html.HTMLImageElement;

/**
 * Preloads engine assets (images and audio) from the browser before the
 * engine creates its first scene, because scene constructors create Sprite
 * and Audio objects synchronously. The asset list lives in an
 * asset-manifest.txt file (one line per asset, generated by the build):
 * "img <path>" for images and "audio <path>" for audio.
 * @author Pimenta
 *
 */
public final class AssetLoader {
  private static final String MANIFEST = "asset-manifest.txt";

  private Runnable onReady;
  private int assetsToLoad;
  private int assetsLoaded;

  private AssetLoader(Runnable onReady) {
    this.onReady = onReady;
  }

  /**
   * Loads all assets listed in the manifest and runs the callback.
   */
  public static void load(Runnable onReady) {
    new AssetLoader(onReady).loadManifest();
  }

  private void loadManifest() {
    XMLHttpRequest xhr = new XMLHttpRequest();
    xhr.setOnReadyStateChange((EventListener<Event>) event -> readyState(xhr));
    xhr.open("GET", MANIFEST, true);
    xhr.send();
  }

  private void readyState(XMLHttpRequest xhr) {
    if (xhr.getReadyState() != XMLHttpRequest.DONE)
      return;

    int status = xhr.getStatus();
    if (status != 200 && status != 0) {
      BrowserConsole.error("uNyan: cannot load " + MANIFEST + " (HTTP " + status
          + "). Serve the web build over HTTP and regenerate the manifest.");
      ready();
      return;
    }

    countManifestAssets(xhr.getResponseText());
    if (assetsToLoad == 0)
      ready();
    else
      startWatchdog();
  }

  /**
   * Some environments (headless browsers without media pipeline, networks
   * with stalled audio requests) never signal audio readiness; after a
   * grace period the game starts anyway (the looping music simply begins
   * once the element becomes ready).
   */
  private void startWatchdog() {
    org.teavm.jso.browser.Window.setTimeout(new org.teavm.jso.browser.TimerHandler() {
      public void onTimer() {
        if (assetsLoaded < assetsToLoad) {
          BrowserConsole.error("uNyan: asset preload watchdog released the game start "
              + "(" + assetsLoaded + "/" + assetsToLoad + " ready)");
          ready();
        }
      }
    }, 5000);
  }

  /**
   * Engine's private use: counts assets and starts loading them.
   */
  private void countManifestAssets(String manifest) {
    String[] lines = manifest.split("\n");
    for (String line : lines) {
      line = line.trim();
      if (line.length() == 0 || line.startsWith("#"))
        continue;
      int space = line.indexOf(' ');
      if (space <= 0)
        continue;
      String kind = line.substring(0, space);
      String path = line.substring(space + 1).trim();
      if ("img".equals(kind))
        loadSprite(path);
      else if ("audio".equals(kind))
        loadAudio(path);
    }
  }

  private void loadSprite(String path) {
    assetsToLoad++;
    HTMLImageElement image = (HTMLImageElement) HTMLDocument.current().createElement("img").cast();
    EventListener<Event> done = event -> spriteDone(path, image);
    image.addEventListener("load", done);
    image.addEventListener("error", done);
    image.setSrc(path);
  }

  private void loadAudio(String path) {
    assetsToLoad++;
    HTMLAudioElement audio = (HTMLAudioElement) HTMLDocument.current().createElement("audio").cast();
    audio.setPreload("auto");
    audio.setSrc(path);
    audio.load();

    EventListener<Event> done = event -> audioDone(path, audio);
    audio.addEventListener("canplay", done);
    audio.addEventListener("canplaythrough", done);
    audio.addEventListener("error", done);
    LoadedAssets.putSound(path, audio);
  }

  private void spriteDone(String path, HTMLImageElement image) {
    if (image.getNaturalWidth() > 0)
      LoadedAssets.putImage(path, image);
    else
      BrowserConsole.error("uNyan: image asset failed to load: " + path);
    assetLoaded();
  }

  private void audioDone(String path, HTMLAudioElement audio) {
    if (audio.getReadyState() < HTMLAudioElement.HAVE_CURRENT_DATA)
      BrowserConsole.error("uNyan: audio asset failed to load: " + path);
    assetLoaded();
  }

  private void assetLoaded() {
    assetsLoaded++;
    if (assetsLoaded >= assetsToLoad)
      ready();
  }

  private void ready() {
    if (onReady == null)
      return;
    Runnable callback = onReady;
    onReady = null;
    callback.run();
  }
}
